-- V5: verified Rolex catalog import. Preserve existing rows and commerce foreign keys.
-- Source: corrected-product-manifest.csv and image-to-product-verification.csv.
-- Prices, currency, inventory, warranty, and brochure-unstated values remain NULL.
ALTER TABLE watches ALTER COLUMN price DROP NOT NULL;
ALTER TABLE watches ALTER COLUMN currency DROP NOT NULL;
ALTER TABLE watches ALTER COLUMN stock_quantity DROP NOT NULL;
ALTER TABLE watches ALTER COLUMN stock_quantity DROP DEFAULT;
ALTER TABLE watches ALTER COLUMN warranty_years DROP DEFAULT;
ALTER TABLE watches ALTER COLUMN movement_type SET DATA TYPE TEXT;
ALTER TABLE watches ADD COLUMN collection_name VARCHAR(100);
ALTER TABLE watches ADD COLUMN collection_slug VARCHAR(100);
ALTER TABLE watches ADD COLUMN case_type_description TEXT;
ALTER TABLE watches ADD COLUMN bezel_description TEXT;
ALTER TABLE watches ADD COLUMN case_back_description TEXT;
ALTER TABLE watches ADD COLUMN winding_crown_description TEXT;
ALTER TABLE watches ADD COLUMN case_diameter_text VARCHAR(50);
ALTER TABLE watches ADD COLUMN water_resistance_text VARCHAR(255);
ALTER TABLE watches ADD COLUMN power_reserve_text VARCHAR(100);
ALTER TABLE watches ADD COLUMN precision_text VARCHAR(100);
ALTER TABLE watches ADD COLUMN oscillator_description TEXT;
ALTER TABLE watches ADD COLUMN winding_description TEXT;
ALTER TABLE watches ADD COLUMN bracelet_type VARCHAR(255);
ALTER TABLE watches ADD COLUMN clasp_description TEXT;
ALTER TABLE watches ADD COLUMN dial_details TEXT;
ALTER TABLE watches ADD COLUMN certification TEXT;
ALTER TABLE watches ADD COLUMN source_pdf VARCHAR(255);
ALTER TABLE watches ADD COLUMN source_filename_product_code VARCHAR(100);
ALTER TABLE watches ADD COLUMN source_cover_page INT;
ALTER TABLE watches ADD COLUMN source_description_page INT;
ALTER TABLE watches ADD COLUMN source_specification_pages VARCHAR(100);
ALTER TABLE watches ADD COLUMN source_image_page INT;
ALTER TABLE watches ADD COLUMN source_image_object VARCHAR(255);
ALTER TABLE watches ADD COLUMN image_source_path VARCHAR(255);
ALTER TABLE watches ADD COLUMN image_sha256 VARCHAR(64);
ALTER TABLE watches ADD COLUMN image_rights_status TEXT;
ALTER TABLE watches ADD COLUMN image_verification_status TEXT;
UPDATE watches SET status = 'ARCHIVED', is_featured = FALSE WHERE status = 'PUBLISHED';
ALTER TABLE watches ADD CONSTRAINT ck_published_catalog_rolex CHECK (status <> 'PUBLISHED' OR brand = 'Rolex');
ALTER TABLE watches ADD CONSTRAINT ck_watch_positive_price CHECK (price IS NULL OR price > 0);
ALTER TABLE watches ADD CONSTRAINT ck_watch_nonnegative_stock CHECK (stock_quantity IS NULL OR stock_quantity >= 0);
CREATE UNIQUE INDEX uq_watches_reference_number ON watches(reference_number);

